import sys
import math

_DEBUG = False

def debug(msg):
    global out, debugCount
    if _DEBUG and debugCount < 200:
        print(msg)
        debugCount += 1

class Main:
    def __init__(self):
        self.N = 0
        self.M = 0
        self.pow = 0
        self.counts = []
        self.dp = []

    def solve(self):
        input_data = sys.stdin.read().strip().split()
        self.N = int(input_data[0])
        self.M = int(input_data[1])
        if self.N < self.M:
            self.N, self.M = self.M, self.N
        self.pow = 1 << self.M
        self.counts = [0] * self.pow
        self.dp = [[[ -1 for _ in range(self.pow)] for _ in range(self.pow)] for _ in range(self.N)]
        for i in range(self.pow):
            self.counts[i] = bin(i).count('1')
            self.dp[0][i][0] = self.counts[i]
        minSpiders = float('inf')
        for y in range(self.N - 1):
            for i in range(self.pow):
                for j in range(self.pow):
                    if self.dp[y][i][j] == -1:
                        continue
                    for k in range(self.pow):
                        if (((i | (i << 1) & ((1 << self.M) - 1)) | (i >> 1) & ((1 << self.M) - 1)) | j | k) & ((1 << self.M) - 1) == (1 << self.M) - 1:
                            val = self.dp[y][i][j] + self.counts[k]
                            if self.dp[y + 1][k][i] == -1 or self.dp[y + 1][k][i] > val:
                                self.dp[y + 1][k][i] = val
        for i in range(self.pow):
            for j in range(self.pow):
                if self.dp[self.N - 1][i][j] != -1 and (((i | (i << 1) & ((1 << self.M) - 1)) | (i >> 1) & ((1 << self.M) - 1)) | j) & ((1 << self.M) - 1) == (1 << self.M) - 1:
                    minSpiders = min(minSpiders, self.dp[self.N - 1][i][j])
        print((self.N * self.M) - minSpiders)

if __name__ == "__main__":
    debugCount = 0
    solver = Main()
    solver.solve()

